const CASCADE_STAGGER = 0.025;
const ROLL_BLUR = "blur(6px)";

const CASCADE_LETTER_VARIANTS: Variants = {
  initial: { opacity: 0, y: "105%", filter: ROLL_BLUR },
  animate: (delay: number = 0) => ({
    opacity: 1,
    y: "0%",
    filter: "blur(0px)",
    transition: { ...SPRING_SWAP, delay },
  }),
  exit: (delay: number = 0) => ({
    opacity: 0,
    y: "-105%",
    filter: ROLL_BLUR,
    transition: { duration: 0.16, ease: EASE_OUT, delay: delay * 0.5 },
  }),
};

const ICON_VARIANTS: Variants = {
  // Width collapses too, so the icon adds/removes its own space smoothly
  // instead of popping the row width in a single frame.
  initial: { opacity: 0, width: 0, scale: 0.7, filter: ROLL_BLUR },
  animate: {
    opacity: 1,
    width: "1.5rem",
    scale: 1,
    filter: "blur(0px)",
    transition: SPRING_SWAP,
  },
  exit: {
    opacity: 0,
    width: 0,
    scale: 0.7,
    filter: ROLL_BLUR,
    transition: { duration: 0.16, ease: EASE_OUT },
  },
};

function IconSlot({ keyId, children }: { keyId: string; children: ReactNode }) {
  const reduce = useReducedMotion();
  return (
    <motion.span
      key={keyId}
      variants={ICON_VARIANTS}
      initial={reduce ? { opacity: 0 } : "initial"}
      animate={reduce ? { opacity: 1 } : "animate"}
      exit={reduce ? { opacity: 0 } : "exit"}
      transition={reduce ? { duration: 0.15 } : undefined}
      className="inline-grid shrink-0 place-items-center overflow-hidden"
    >
      {children}
    </motion.span>
  );
}

function TextSlot({
  value,
  children,
}: {
  value: string;
  children: ReactNode;
}) {
  const reduce = useReducedMotion();
  const measureRef = useRef<HTMLSpanElement>(null);
  const [width, setWidth] = useState<number>();
  const label = typeof children === "string" ? children : null;
  const cascade = label !== null && !reduce;

  // Measure strings with the same per-letter layout as the cascade. Measuring
  // the whole string preserves kerning, which can make it narrower than the
  // inline-block letters and clip the final glyph during the width animation.
  useLayoutEffect(() => {
    const nextWidth = measureRef.current?.offsetWidth;
    if (!nextWidth) return;
    setWidth((current) => (current === nextWidth ? current : nextWidth));
  });

  return (
    <motion.span
      initial={false}
      animate={{ width }}
      transition={reduce ? { duration: 0 } : SPRING_SWAP}
      className="relative inline-block overflow-hidden whitespace-nowrap align-bottom"
    >
      <span
        ref={measureRef}
        aria-hidden
        className="invisible inline-block whitespace-nowrap"
      >
        {cascade
          ? label.split("").map((char, index) => (
              <span
                // biome-ignore lint/suspicious/noArrayIndexKey: position is the slot identity.
                key={index}
                className="inline-block whitespace-pre"
              >
                {char}
              </span>
            ))
          : children}
      </span>

      {cascade ? (
        <>
          <span className="sr-only">{label}</span>
          <AnimatePresence initial={false}>
            <motion.span
              key={`cascade-${value}`}
              aria-hidden
              initial="initial"
              animate="animate"
              exit="exit"
              className="absolute left-0 top-0 inline-block whitespace-pre"
            >
              {label.split("").map((char, index) => (
                <motion.span
                  // biome-ignore lint/suspicious/noArrayIndexKey: position is the slot identity.
                  key={index}
                  custom={index * CASCADE_STAGGER}
                  variants={CASCADE_LETTER_VARIANTS}
                  // Own states: a label that swaps away and straight back
                  // re-enters mid-exit, and only owned targets are restored.
                  initial="initial"
                  animate="animate"
                  exit="exit"
                  className="inline-block whitespace-pre will-change-[opacity,filter,transform]"
                >
                  {char}
                </motion.span>
              ))}
            </motion.span>
          </AnimatePresence>
        </>
      ) : (
        <AnimatePresence initial={false}>
          <motion.span
            key={`text-${value}`}
            initial={reduce ? { opacity: 0 } : { opacity: 0, y: 14, filter: ROLL_BLUR }}
            animate={reduce ? { opacity: 1 } : { opacity: 1, y: 0, filter: "blur(0px)" }}
            exit={reduce ? { opacity: 0 } : { opacity: 0, y: -14, filter: ROLL_BLUR }}
            transition={reduce ? { duration: 0.15 } : SPRING_SWAP}
            className="absolute left-0 top-0 inline-block will-change-[opacity,filter,transform]"
          >
            {children}
          </motion.span>
        </AnimatePresence>
      )}
    </motion.span>
  );
}

export const StatefulButton = forwardRef<HTMLButtonElement, StatefulButtonProps>(function StatefulButton(
  {
    state = "idle",
    children,
    loadingText = "Loading",
    successText = "Done",
    errorText = "Try again",
    icon,
    disabled,
    ...rest
  },
  ref,
) {
  const isBusy = state === "loading";
  const stateText =
    state === "loading"
      ? loadingText
      : state === "success"
        ? successText
        : state === "error"
        ? errorText
        : children;
  const textKey =
    typeof stateText === "string" ? `${state}-${stateText}` : state;

  return (
    <Button ref={ref} disabled={disabled || isBusy} aria-busy={isBusy} whileHover={undefined} {...rest}>
      <span
        aria-live="polite"
        className="relative inline-flex items-center justify-center overflow-hidden"
      >
        <AnimatePresence initial={false}>
          {state === "loading" ? (
            <IconSlot keyId="loading-icon">
              <Loader2 className="h-4 w-4 animate-spin" />
            </IconSlot>
          ) : null}
          {state === "success" ? (
            <IconSlot keyId="success-icon">
              <Check className="h-4 w-4" />
            </IconSlot>
          ) : null}
          {state === "error" ? (
            <IconSlot keyId="error-icon">
              <X className="h-4 w-4" />
            </IconSlot>
          ) : null}
        </AnimatePresence>

        <TextSlot value={textKey}>{stateText}</TextSlot>

        <AnimatePresence initial={false}>
          {state === "idle" && icon ? (
            <IconSlot keyId="idle-icon">{icon}</IconSlot>
          ) : null}
        </AnimatePresence>
      </span>
    </Button>
  );
});

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId } from "react";
import { EASE_OUT, SPRING_PRESS } from "@/lib/ease";
import { cn } from "@/lib/utils";

const CHECK_PATH = "M5 13l4 4L19 7";
const INDETERMINATE_PATH = "M6 12h12";

export interface CheckboxProps {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  disabled?: boolean;
  indeterminate?: boolean;
  label?: string;
  /** Supporting text under the label, announced as the description rather than the name. */
  description?: string;
  className?: string;
  id?: string;
  "aria-label"?: string;
  /** Associates an external message (e.g. a form error) with the control. */
  "aria-describedby"?: string;
}

export function Checkbox({
  checked,
  onCheckedChange,
  disabled,
  indeterminate,
  label,
  description,
  className,
  id: idProp,
  "aria-label": ariaLabel,
  "aria-describedby": ariaDescribedBy,
}: CheckboxProps) {
  const autoId = useId();
  const id = idProp ?? autoId;
  const reduce = useReducedMotion();
  const showMark = checked || indeterminate;
  const path = indeterminate ? INDETERMINATE_PATH : CHECK_PATH;
  const descriptionId = description ? `${id}-description` : undefined;
  // The wrapping <label> would fold the description into the name, so name from the label text alone.
  const labelId = description && label && !ariaLabel ? `${id}-label` : undefined;
  const describedBy =
    [ariaDescribedBy, descriptionId].filter(Boolean).join(" ") || undefined;

  return (
    <label
      htmlFor={id}
      className={cn(
        "inline-flex gap-3",
        description ? "items-start" : "items-center",
        disabled ? "cursor-not-allowed" : "cursor-pointer",
        className,
      )}
    >
      <motion.button
        id={id}
        type="button"
        role="checkbox"
        aria-checked={indeterminate ? "mixed" : checked}
        aria-label={ariaLabel}
        aria-labelledby={labelId}
        aria-describedby={describedBy}
        disabled={disabled}
        onClick={() => !disabled && onCheckedChange(!checked)}
        whileTap={reduce || disabled ? undefined : { scale: 0.92 }}
        transition={SPRING_PRESS}
        data-state={
          checked ? "checked" : indeterminate ? "indeterminate" : "unchecked"
        }
        className={cn(
          "inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 outline-none transition-colors duration-200",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:cursor-not-allowed disabled:opacity-60",
          showMark
            ? "border-primary bg-primary text-primary-foreground"
            : "border-muted-foreground/50 bg-background hover:border-muted-foreground",
        )}
      >
        <AnimatePresence initial={false}>
          {showMark ? (
            <motion.svg
              key={indeterminate ? "indeterminate" : "checked"}
              width="12"
              height="12"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={3}
              strokeLinecap="round"
              strokeLinejoin="round"
              initial={reduce ? { opacity: 1 } : { opacity: 0, scale: 0.5 }}
              animate={reduce ? { opacity: 1 } : { opacity: 1, scale: 1 }}
              exit={
                reduce
                  ? { opacity: 0 }
                  : { opacity: 0, scale: 0.5, filter: "blur(4px)" }
              }
              transition={
                reduce ? { duration: 0 } : { duration: 0.16, ease: EASE_OUT }
              }
              aria-hidden
            >
              <title>{indeterminate ? "Partially selected" : "Selected"}</title>
              <motion.path
                d={path}
                initial={reduce ? { pathLength: 1 } : { pathLength: 0 }}
                animate={{ pathLength: 1 }}
                transition={
                  reduce
                    ? { duration: 0 }
                    : {
                        duration: indeterminate ? 0.2 : 0.3,
                        ease: EASE_OUT,
                        delay: 0.04,
                      }
                }
              />
            </motion.svg>
          ) : null}
        </AnimatePresence>
      </motion.button>
      {label || description ? (
        <span className={cn("flex min-w-0 flex-col gap-0.5 select-none", disabled && "opacity-60")}>
          {label ? (
            <span
              id={labelId}
              // Geist sits low in a 20px line; a 16px line lifts the text onto the control.
              className={cn("text-sm text-foreground", description && "leading-4")}
            >
              {label}
            </span>
          ) : null}
          {description ? (
            <span id={descriptionId} className="text-xs text-muted-foreground">
              {description}
            </span>
          ) : null}
        </span>
      ) : null}
    </label>
  );
}

"use client";

import {
  AnimatePresence,
  animate,
  motion,
  useReducedMotion,
} from "motion/react";
import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  useState,
  type InputHTMLAttributes,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";

export type InputClassNames = {
  root?: string;
  label?: string;
  field?: string;
  input?: string;
  leftIcon?: string;
  rightIcon?: string;
  successIcon?: string;
  errorMessage?: string;
};

export interface InputProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "defaultValue" | "onChange"
> {
  label?: string;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** Truthy error triggers a shake, red border and (if a string) a message. */
  error?: string | boolean;
  /** Reserve one message line so validation does not shift nearby content. */
  reserveErrorLine?: boolean;
  success?: boolean;
  leftIcon?: ReactNode;
  rightIcon?: ReactNode;
  className?: string;
  classNames?: InputClassNames;
}

export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  {
    label,
    value: valueProp,
    defaultValue,
    onChange,
    onFocus,
    onBlur,
    error,
    reserveErrorLine = false,
    success,
    leftIcon,
    rightIcon,
    className,
    classNames,
    disabled,
    id: idProp,
    type,
    ...rest
  },
  ref,
) {
  const reactId = useId();
  const id = idProp ?? reactId;
  const reduce = useReducedMotion();

  const controlled = valueProp !== undefined;
  const [internal, setInternal] = useState(defaultValue ?? "");
  const value = controlled ? (valueProp ?? "") : internal;

  const [focused, setFocused] = useState(false);

  const fieldRef = useRef<HTMLDivElement>(null);

  const hasError = Boolean(error);
  const errorMessage = typeof error === "string" ? error : null;

  // Right edge shows the success check, otherwise the caller's right icon.
  const rightSlot = success ? null : rightIcon;

  // Shake the field when an error appears.
  useEffect(() => {
    if (!fieldRef.current || reduce || !hasError) return;
    animate(
      fieldRef.current,
      { x: [0, -6, 6, -4, 4, -2, 0] },
      { duration: 0.45 },
    );
  }, [hasError, reduce]);

  const handleChange = (next: string) => {
    if (!controlled) setInternal(next);
    onChange?.(next);
  };

  return (
    <div
      className={cn("flex flex-col gap-1.5", className, classNames?.root)}
    >
      {label ? (
        <label
          htmlFor={id}
          className={cn(
            "px-1 text-sm font-medium text-foreground",
            classNames?.label,
          )}
        >
          {label}
        </label>
      ) : null}

      <div
        ref={fieldRef}
        data-state={
          hasError
            ? "error"
            : success
              ? "success"
              : focused
                ? "focused"
                : "idle"
        }
        className={cn(
          "relative h-11 overflow-hidden rounded-full border transition-colors duration-200",
          "border-border",
          focused && !hasError && "border-foreground/40 ring-2 ring-ring/40",
          hasError && "border-destructive ring-2 ring-destructive/25",
          disabled && "opacity-60",
          classNames?.field,
        )}
      >
        {leftIcon ? (
          <span
            className={cn(
              "pointer-events-none absolute left-3 top-1/2 flex -translate-y-1/2 items-center text-muted-foreground [&_svg]:h-4 [&_svg]:w-4",
              classNames?.leftIcon,
            )}
          >
            {leftIcon}
          </span>
        ) : null}

        <input
          ref={ref}
          id={id}
          type={type}
          value={value}
          disabled={disabled}
          aria-invalid={hasError || undefined}
          aria-describedby={errorMessage ? `${id}-error` : undefined}
          {...rest}
          onChange={(e) => handleChange(e.target.value)}
          onFocus={(event) => {
            setFocused(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setFocused(false);
            onBlur?.(event);
          }}
          className={cn(
            "peer h-full w-full bg-transparent text-base leading-6 text-foreground caret-foreground outline-none",
            "placeholder:text-muted-foreground/60",
            leftIcon ? "pl-10" : "pl-3.5",
            rightSlot || success ? "pr-10" : "pr-3.5",
            disabled && "cursor-not-allowed",
            classNames?.input,
          )}
        />

        {success ? (
          <motion.svg
            viewBox="0 0 24 24"
            fill="none"
            className={cn(
              "absolute right-3.5 top-1/2 h-5 w-5 -translate-y-1/2 text-(--color-success)",
              classNames?.successIcon,
            )}
          >
            <motion.path
              d="M5 12.5l4.5 4.5L19 7.5"
              stroke="currentColor"
              strokeWidth={2.5}
              strokeLinecap="round"
              strokeLinejoin="round"
              initial={reduce ? { pathLength: 1 } : { pathLength: 0 }}
              animate={{ pathLength: 1 }}
              transition={{ duration: 0.35, ease: "easeOut" }}
            />
          </motion.svg>
        ) : rightSlot ? (
          <span
            className={cn(
              "absolute right-0 top-0 flex h-full items-center text-muted-foreground [&_button]:grid [&_button]:size-11 [&_button]:place-items-center [&_svg]:h-4 [&_svg]:w-4",
              classNames?.rightIcon,
            )}
          >
            {rightSlot}
          </span>
        ) : null}
      </div>

      <div className={reserveErrorLine ? "min-h-4" : "contents"}>
        <AnimatePresence initial={false}>
          {errorMessage ? (
            <motion.p
              id={`${id}-error`}
              role="alert"
              initial={
                reduce
                  ? { opacity: 0 }
                  : { opacity: 0, y: -4, filter: "blur(4px)" }
              }
              animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
              exit={
                reduce
                  ? { opacity: 0 }
                  : { opacity: 0, y: -4, filter: "blur(4px)" }
              }
              transition={{ duration: 0.2 }}
              className={cn(
                "px-1 text-xs text-destructive",
                classNames?.errorMessage,
              )}
            >
              {errorMessage}
            </motion.p>
          ) : null}
        </AnimatePresence>
      </div>
    </div>
  );
});

"use client";

import { motion, useMotionValue, useReducedMotion, useSpring } from "motion/react";
import { useRef, type ReactNode } from "react";
import { SPRING_MOUSE } from "@/lib/ease";
import { useHoverCapable } from "@/lib/hooks/use-hover-capable";
import { cn } from "@/lib/utils";

export interface MagneticProps {
  children: ReactNode;
  strength?: number;
  className?: string;
}

export function Magnetic({ children, strength = 0.35, className }: MagneticProps) {
  const ref = useRef<HTMLDivElement>(null);
  const reduce = useReducedMotion();
  const canHover = useHoverCapable();
  // Decorative cursor-follow: skip on touch (phantom hover) and reduced motion.
  const enabled = !reduce && canHover;
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const sx = useSpring(x, SPRING_MOUSE);
  const sy = useSpring(y, SPRING_MOUSE);

  const onMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const el = ref.current;
    if (!el || !enabled) return;
    const rect = el.getBoundingClientRect();
    x.set((e.clientX - rect.left - rect.width / 2) * strength);
    y.set((e.clientY - rect.top - rect.height / 2) * strength);
  };

  const onLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.div
      ref={ref}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
      style={{ x: sx, y: sy }}
      className={cn("inline-block", className)}
    >
      {children}
    </motion.div>
  );
}

"use client";

import { motion, MotionConfig, useReducedMotion } from "motion/react";
import {
  createContext,
  type KeyboardEvent,
  useCallback,
  useContext,
  useId,
  useLayoutEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { SPRING_LAYOUT, SPRING_PRESS } from "@/lib/ease";
import { cn } from "@/lib/utils";

type RadioCtx = {
  value: string;
  setValue: (value: string) => void;
  layoutId: string;
  /**
   * The one option Tab reaches: the selected option, or the first enabled one
   * when nothing enabled is selected. `null` until the options have
   * registered, when every enabled option stays reachable.
   */
  tabStop: string | null;
  register: (value: string, disabled: boolean) => void;
  unregister: (value: string) => void;
};

const RadioCtx = createContext<RadioCtx | null>(null);

function useRadioGroup() {
  const ctx = useContext(RadioCtx);
  if (!ctx) {
    throw new Error("RadioGroupItem must be used inside <RadioGroup>");
  }
  return ctx;
}

export interface RadioGroupProps {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  children: ReactNode;
  className?: string;
  orientation?: "vertical" | "horizontal";
  /** Accessible name for the group when no visible label names it. */
  "aria-label"?: string;
  /** Id of a visible element that names the group. */
  "aria-labelledby"?: string;
}

export function RadioGroup({
  value,
  defaultValue = "",
  onValueChange,
  children,
  className,
  orientation = "vertical",
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
}: RadioGroupProps) {
  const [internal, setInternal] = useState(defaultValue);
  const layoutId = useId();
  const reduce = useReducedMotion();
  const controlled = value !== undefined;
  const current = controlled ? value : internal;
  const setValue = useCallback(
    (next: string) => {
      if (!controlled) setInternal(next);
      onValueChange?.(next);
    },
    [controlled, onValueChange],
  );
  const [options, setOptions] = useState<Map<string, boolean>>(new Map());
  const register = useCallback((option: string, disabled: boolean) => {
    setOptions((map) =>
      map.get(option) === disabled ? map : new Map(map).set(option, disabled),
    );
  }, []);
  const unregister = useCallback((option: string) => {
    setOptions((map) => {
      if (!map.has(option)) return map;
      const next = new Map(map);
      next.delete(option);
      return next;
    });
  }, []);
  // Resolved during render so the group has exactly one tab stop in the same
  // commit that changes the selection or the options.
  let tabStop: string | null = null;
  if (options.size > 0) {
    const enabled = Array.from(options).filter(([, disabled]) => !disabled);
    tabStop = enabled.some(([option]) => option === current)
      ? current
      : (enabled[0]?.[0] ?? "");
  }
  const contextValue = useMemo(
    () => ({ value: current, setValue, layoutId, tabStop, register, unregister }),
    [current, layoutId, setValue, tabStop, register, unregister],
  );

  return (
    <MotionConfig transition={reduce ? { duration: 0 } : SPRING_LAYOUT}>
      <RadioCtx.Provider value={contextValue}>
        <div
          role="radiogroup"
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          className={cn(
            "flex gap-3",
            orientation === "vertical" ? "flex-col" : "flex-row flex-wrap",
            className,
          )}
        >
          {children}
        </div>
      </RadioCtx.Provider>
    </MotionConfig>
  );
}

export interface RadioGroupItemProps {
  value: string;
  label?: string;
  /** Supporting text under the label, announced as the description rather than the name. */
  description?: string;
  disabled?: boolean;
  className?: string;
  id?: string;
}

export function RadioGroupItem({
  value,
  label,
  description,
  disabled,
  className,
  id: idProp,
}: RadioGroupItemProps) {
  const {
    value: groupValue,
    setValue,
    layoutId,
    tabStop,
    register,
    unregister,
  } = useRadioGroup();
  const autoId = useId();
  const id = idProp ?? autoId;
  const reduce = useReducedMotion();
  const selected = groupValue === value;
  const descriptionId = description ? `${id}-description` : undefined;
  // The wrapping <label> would fold the description into the name, so name from the label text alone.
  const labelId = description && label ? `${id}-label` : undefined;

  useLayoutEffect(() => {
    register(value, Boolean(disabled));
  }, [register, value, disabled]);
  useLayoutEffect(() => () => unregister(value), [unregister, value]);

  const reachable =
    !disabled && (tabStop === null ? true : tabStop === value);

  // Arrow keys move to the next enabled option in the group, wrapping at the
  // ends, and select it as focus arrives, like native radio buttons.
  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const step =
      event.key === "ArrowDown" || event.key === "ArrowRight"
        ? 1
        : event.key === "ArrowUp" || event.key === "ArrowLeft"
          ? -1
          : 0;
    if (!step) return;
    const group = event.currentTarget.closest('[role="radiogroup"]');
    const radios = Array.from(
      group?.querySelectorAll<HTMLButtonElement>('[role="radio"]') ?? [],
    ).filter(
      (radio) =>
        !radio.disabled &&
        radio.closest('[role="radiogroup"]') === group,
    );
    const at = radios.indexOf(event.currentTarget);
    if (at < 0 || radios.length < 2) return;
    event.preventDefault();
    const next = radios[(at + step + radios.length) % radios.length];
    next.focus();
    next.click();
  };

  return (
    <label
      htmlFor={id}
      className={cn(
        "inline-flex gap-3",
        description ? "items-start" : "items-center",
        disabled ? "cursor-not-allowed" : "cursor-pointer",
        className,
      )}
    >
      <motion.button
        id={id}
        type="button"
        role="radio"
        aria-checked={selected}
        aria-labelledby={labelId}
        aria-describedby={descriptionId}
        disabled={disabled}
        tabIndex={reachable ? 0 : -1}
        onClick={() => !disabled && setValue(value)}
        onKeyDown={onKeyDown}
        whileTap={reduce || disabled ? undefined : { scale: 0.92 }}
        transition={SPRING_PRESS}
        data-state={selected ? "checked" : "unchecked"}
        className={cn(
          "relative inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 outline-none transition-colors duration-200",
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
          "disabled:cursor-not-allowed disabled:opacity-60",
          selected
            ? "border-primary"
            : "border-muted-foreground/50 hover:border-muted-foreground",
        )}
      >
        {selected ? (
          <motion.span
            layoutId={layoutId}
            className="absolute inset-1 rounded-full bg-primary"
            transition={reduce ? { duration: 0 } : SPRING_LAYOUT}
          />
        ) : null}
      </motion.button>
      {label || description ? (
        <span className={cn("flex min-w-0 flex-col gap-0.5 select-none", disabled && "opacity-60")}>
          {label ? (
            <span
              id={labelId}
              // Geist sits low in a 20px line; a 16px line lifts the text onto the control.
              className={cn("text-sm text-foreground", description && "leading-4")}
            >
              {label}
            </span>
          ) : null}
          {description ? (
            <span id={descriptionId} className="text-xs text-muted-foreground">
              {description}
            </span>
          ) : null}
        </span>
      ) : null}
    </label>
  );
}

// Shared motion tokens. Easing curves mirror the CSS custom properties in
// globals.css; springs are the canonical physics used across components.
// Strong custom variants — defaults like `ease-in`/`ease-out` feel weak.

export const EASE_OUT = [0.16, 1, 0.3, 1] as const;
export const EASE_IN_OUT = [0.77, 0, 0.175, 1] as const;
export const EASE_DRAWER = [0.32, 0.72, 0, 1] as const;

/** CSS string form of EASE_OUT for inline style transitions. */
export const EASE_OUT_CSS = "cubic-bezier(0.16, 1, 0.3, 1)";

/** Press feedback on buttons and other tappable surfaces. */
export const SPRING_PRESS = {
  type: "spring",
  stiffness: 500,
  damping: 30,
  mass: 0.6,
} as const;

/** Content swaps — label/icon slots trading places inside a control. */
export const SPRING_SWAP = {
  type: "spring",
  stiffness: 460,
  damping: 30,
  mass: 0.55,
} as const;

/** Overlay panel entrances — modals and sheets summoned by pointer. */
export const SPRING_PANEL = {
  type: "spring",
  stiffness: 420,
  damping: 40,
  mass: 0.5,
} as const;

/** Shared-layout glides — pills, indicators and panels morphing between positions. */
export const SPRING_LAYOUT = {
  type: "spring",
  stiffness: 360,
  damping: 32,
  mass: 0.6,
} as const;

/** Cursor-follow physics for decorative mouse tracking (magnetic, tilt, dock). */
export const SPRING_MOUSE = {
  stiffness: 200,
  damping: 15,
  mass: 0.3,
} as const;

/** Dragged handles and fills (sliders) — critically damped `useSpring` config,
 * so the value follows the pointer butterily and never rebounds off an end. */
export const SPRING_GLIDE = {
  stiffness: 700,
  damping: 50,
  mass: 0.5,
} as const;

"use client";

import { useEffect, useState } from "react";

/**
 * Returns true only on devices that have a true hover (mouse / trackpad).
 * Touch devices fire phantom `:hover` on tap that sticks until tap-elsewhere
 * — gate hover-only effects (scale lifts, magnetic pulls) behind this.
 */
export function useHoverCapable() {
  const [canHover, setCanHover] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
    const update = () => setCanHover(mq.matches);
    update();
    mq.addEventListener?.("change", update);
    return () => mq.removeEventListener?.("change", update);
  }, []);

  return canHover;
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

"use client";
// beui.dev/components/motion/arc-picker

import {
  animate,
  type AnimationPlaybackControls,
  motion,
  type MotionValue,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import {
  type ComponentProps,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { SPRING_GLIDE, SPRING_LAYOUT } from "@/lib/ease";
import { cn } from "@/lib/utils";

export type ArcPickerOption = {
  value: string;
  label: string;
  disabled?: boolean;
};

export type ArcPickerSide = "top" | "bottom" | "left" | "right";

export type ArcPickerProps = Omit<
  ComponentProps<"div">,
  "children" | "defaultValue" | "onChange"
> & {
  options: readonly ArcPickerOption[];
  value?: string;
  defaultValue?: string;
  /** Called for each enabled choice crossed during scrolling, dragging and momentum. */
  onValueChange?: (value: string) => void;
  /** The side the arc bows toward. Top and bottom scroll horizontally. */
  side?: ArcPickerSide;
  /** Radius in pixels. Larger radii make a gentler curve. */
  radius?: number;
  /** Minimum spacing along the arc. Horizontal sides also make room for label widths. */
  itemHeight?: number;
  visibleCount?: number;
  disabled?: boolean;
  name?: string;
};

// A short velocity projection lets a flick coast through several detents
// before the shared layout spring settles it, without a long free-running loop.
const COAST_SECONDS = 0.18;
const WHEEL_SETTLE_MS = 120;
// Reserve room for the glyphs and their small outward movement without
// animating padding or changing any label's measured width.
const BRACKET_SPACE = 24;
const BRACKET_GAP = 4;
const BRACKET_EXPANSION = 6;
const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

function ArcOption({
  option,
  index,
  position,
  verticalAnchor,
  radius,
  itemHeight,
  visibleCount,
  side,
  selected,
  disabled,
  setRef,
  onSelect,
}: {
  option: ArcPickerOption;
  index: number;
  position: MotionValue<number>;
  verticalAnchor: number | string;
  radius: number;
  itemHeight: number;
  visibleCount: number;
  side: ArcPickerSide;
  selected: boolean;
  disabled: boolean;
  setRef: (element: HTMLButtonElement | null) => void;
  onSelect: () => void;
}) {
  const horizontal = side === "top" || side === "bottom";
  const transform = useTransform(position, (at) => {
    const angle = clamp(((index - at) * itemHeight) / radius, -1.5, 1.5);
    const bend = radius * (1 - Math.cos(angle));
    const along = radius * Math.sin(angle);
    const x = horizontal ? along : side === "left" ? bend : -bend;
    const y = horizontal ? (side === "top" ? bend : -bend) : along;
    const rotation =
      ((side === "left" || side === "bottom" ? -angle : angle) * 180) / Math.PI;
    const anchor = horizontal ? "-50%" : side === "left" ? "-100%" : "0%";
    return `translate3d(${x}px, ${y}px, 0) translate(${anchor}, -50%) rotate(${rotation}deg)`;
  });
  const opacity = useTransform(position, (at) => {
    const distance = Math.abs(index - at);
    return (
      clamp((visibleCount / 2 + 0.5 - distance) / 1.5, 0, 1) *
      (disabled || option.disabled ? 0.35 : 1)
    );
  });
  const pointerEvents = useTransform(position, (at) =>
    Math.abs(index - at) < visibleCount / 2 ? "auto" : "none",
  );

  return (
    <motion.button
      ref={setRef}
      type="button"
      role="radio"
      aria-checked={selected}
      disabled={disabled || option.disabled}
      tabIndex={selected && !disabled && !option.disabled ? 0 : -1}
      data-slot="arc-picker-option"
      data-value={option.value}
      data-selected={selected || undefined}
      onClick={(event) => {
        if (!event.defaultPrevented) onSelect();
      }}
      className={cn(
        "absolute rounded-md px-2 py-1 text-2xl font-light whitespace-nowrap outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-35",
        horizontal && "text-center",
        !horizontal && (side === "left" ? "text-right" : "text-left"),
        selected ? "text-primary" : "text-muted-foreground",
      )}
      style={{
        top: horizontal ? (side === "top" ? 36 : "calc(100% - 36px)") : "50%",
        left: horizontal ? "50%" : verticalAnchor,
        transformOrigin: horizontal
          ? "center"
          : side === "left"
            ? "right center"
            : "left center",
        maxWidth: horizontal ? "calc(100% - 4rem)" : "calc(100% - 3rem)",
        transform,
        opacity,
        pointerEvents,
      }}
    >
      <span
        data-slot="arc-picker-label"
        className="block overflow-hidden text-ellipsis"
      >
        {option.label}
      </span>
    </motion.button>
  );
}

function ArcSelectionFrame({
  width,
  expansion,
  side,
  verticalAnchor,
  visible,
}: {
  width: MotionValue<number>;
  expansion: MotionValue<number>;
  side: ArcPickerSide;
  verticalAnchor: number | string;
  visible: boolean;
}) {
  const horizontal = side === "top" || side === "bottom";
  const leading = useTransform<number, string>(
    [width, expansion],
    ([size = 0, amount = 0]) => {
      const extent = horizontal ? size / 2 : side === "left" ? size : 0;
      const gap = BRACKET_GAP + clamp(amount, 0, 1) * BRACKET_EXPANSION;
      return `translate3d(${-extent - gap}px, -50%, 0) scaleY(${1 - clamp(amount, 0, 1) * 0.08})`;
    },
  );
  const trailing = useTransform<number, string>(
    [width, expansion],
    ([size = 0, amount = 0]) => {
      const extent = horizontal ? size / 2 : side === "right" ? size : 0;
      const gap = BRACKET_GAP + clamp(amount, 0, 1) * BRACKET_EXPANSION;
      return `translate3d(${extent + gap}px, -50%, 0) scaleY(${1 - clamp(amount, 0, 1) * 0.08})`;
    },
  );
  const opacity = useTransform(width, (size) => (size > 0 ? 0.85 : 0));

  return (
    <div
      aria-hidden="true"
      data-slot="arc-picker-selection-frame"
      className="pointer-events-none absolute h-0 w-0 text-2xl font-light text-primary"
      style={{
        top: horizontal ? (side === "top" ? 36 : "calc(100% - 36px)") : "50%",
        left: horizontal ? "50%" : verticalAnchor,
        visibility: visible ? undefined : "hidden",
      }}
    >
      <motion.span
        data-slot="arc-picker-bracket"
        data-edge="leading"
        className="absolute right-0"
        style={{ transform: leading, opacity }}
      >
        [
      </motion.span>
      <motion.span
        data-slot="arc-picker-bracket"
        data-edge="trailing"
        className="absolute left-0"
        style={{ transform: trailing, opacity }}
      >
        ]
      </motion.span>
    </div>
  );
}

/** A radial single-choice picker with drag momentum and native button controls. */
export function ArcPicker({
  options,
  value,
  defaultValue,
  onValueChange,
  side = "right",
  radius = 280,
  itemHeight = 48,
  visibleCount = 7,
  disabled = false,
  name,
  className,
  style,
  onKeyDown,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onLostPointerCapture,
  onFocusCapture,
  onBlurCapture,
  onClickCapture,
  "aria-label": label = "Choose an option",
  "aria-describedby": describedBy,
  ...props
}: ArcPickerProps) {
  const reducedMotion = useReducedMotion();
  const horizontal = side === "top" || side === "bottom";
  const instructionsId = useId();
  const root = useRef<HTMLDivElement>(null);
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const first = options.find((option) => !option.disabled)?.value;
  const [internalValue, setInternalValue] = useState(defaultValue ?? first);
  const controlled = value !== undefined;
  const candidate = controlled ? value : internalValue;
  const selectedValue = options.some(
    (option) => option.value === candidate && !option.disabled,
  )
    ? candidate
    : first;
  // Resolve identity in the same render as changed options. A removed choice
  // cannot reappear later and silently restore an abandoned selection.
  if (!controlled && internalValue !== selectedValue)
    setInternalValue(selectedValue);
  const selectedIndex = Math.max(
    0,
    options.findIndex((option) => option.value === selectedValue),
  );
  const safeRadius = Math.max(120, Number.isFinite(radius) ? radius : 280);
  const rowHeight = Math.max(32, Number.isFinite(itemHeight) ? itemHeight : 48);
  const count = Math.max(
    3,
    Number.isFinite(visibleCount) ? Math.floor(visibleCount) : 7,
  );
  const [measurements, setMeasurements] = useState({ width: 0, labelWidth: 0 });
  const labelsKey = JSON.stringify(options.map((option) => option.label));
  const spacing = horizontal
    ? Math.max(rowHeight, measurements.labelWidth + BRACKET_SPACE * 2)
    : rowHeight;
  const verticalInset = Math.max(
    BRACKET_SPACE,
    Math.min(
      measurements.width * 0.42,
      measurements.width - measurements.labelWidth - BRACKET_SPACE,
    ),
  );
  const verticalAnchor = measurements.width
    ? side === "left"
      ? measurements.width - verticalInset
      : verticalInset
    : side === "left"
      ? "58%"
      : "42%";
  const curveRadius = horizontal
    ? Math.max(safeRadius, spacing * 2)
    : safeRadius;
  const shownCount = horizontal
    ? Math.min(
        count,
        Math.max(1, (measurements.width || count * spacing) / spacing),
      )
    : count;
  const horizontalHeight = Math.ceil(
    Math.max(
      rowHeight * 2,
      curveRadius *
        (1 -
          Math.cos(
            Math.min(1.35, (shownCount * spacing) / (2 * curveRadius)),
          )) +
        rowHeight +
        24,
    ),
  );
  const position = useMotionValue(selectedIndex);
  const activity = useMotionValue(0);
  const expansion = useSpring(activity, SPRING_GLIDE);
  const frameTarget = useMotionValue(0);
  const frameWidth = useSpring(frameTarget, SPRING_LAYOUT);
  const frameMeasured = useRef(false);
  const animation = useRef<AnimationPlaybackControls | null>(null);
  const wheelTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const wheelTarget = useRef<number | null>(null);
  const reconcileFrame = useRef(0);
  const request = useRef(selectedValue);
  const tracking = useRef(false);
  const instant = useRef(false);
  const drag = useRef<{
    id: number;
    coordinate: number;
    position: number;
    lastCoordinate: number;
    time: number;
    velocity: number;
    moved: boolean;
  } | null>(null);
  const suppressClick = useRef(false);
  const focusWithin = useRef(false);
  const optionsKey = JSON.stringify(
    options.map((option) => [option.value, !!option.disabled]),
  );
  const configuration = JSON.stringify([
    optionsKey,
    side,
    spacing,
    disabled,
    !!reducedMotion,
  ]);
  const previousConfiguration = useRef(configuration);
  const latest = useRef({
    options,
    selectedIndex,
    selectedValue,
    controlled,
    disabled,
    reducedMotion,
    spacing,
    horizontal,
    onValueChange,
  });
  useLayoutEffect(() => {
    latest.current = {
      options,
      selectedIndex,
      selectedValue,
      controlled,
      disabled,
      reducedMotion,
      spacing,
      horizontal,
      onValueChange,
    };
  });

  const measureFrame = useCallback(() => {
    const current = latest.current;
    const width =
      buttons.current.get(current.selectedValue ?? "")?.offsetWidth ?? 0;
    frameTarget.set(width);
    // The first measurement and keyboard changes are immediate. Pointer
    // selections retarget the same two glyphs, preserving spring velocity.
    if (!frameMeasured.current || instant.current || current.reducedMotion)
      frameWidth.jump(width);
    frameMeasured.current = true;
  }, [frameTarget, frameWidth]);

  useLayoutEffect(() => {
    // Observe untransformed sizes: animated bounds would change the spacing
    // every frame. Font loading and responsive text sizes still trigger this.
    void optionsKey;
    void labelsKey;
    const element = root.current;
    if (!element) return;
    const measure = () => {
      const width = element.clientWidth;
      const labelWidth = Math.max(
        0,
        ...Array.from(buttons.current.values(), (button) => button.offsetWidth),
      );
      setMeasurements((previous) =>
        previous.width === width && previous.labelWidth === labelWidth
          ? previous
          : { width, labelWidth },
      );
      // A font or truncated label can resize while the largest label stays
      // the same width. Update the frame even when React needs no new measure.
      measureFrame();
    };
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    for (const button of buttons.current.values()) observer.observe(button);
    measure();
    return () => observer.disconnect();
  }, [optionsKey, labelsKey, measureFrame]);

  useLayoutEffect(() => {
    void selectedValue;
    void reducedMotion;
    measureFrame();
  }, [selectedValue, reducedMotion, measureFrame]);

  const stop = useCallback(() => {
    animation.current?.stop();
    animation.current = null;
    if (wheelTimer.current) clearTimeout(wheelTimer.current);
    wheelTimer.current = null;
    wheelTarget.current = null;
    cancelAnimationFrame(reconcileFrame.current);
    tracking.current = false;
    activity.set(0);
    if (latest.current.reducedMotion) expansion.jump(0);
    const pointer = drag.current;
    drag.current = null;
    if (pointer && root.current?.hasPointerCapture(pointer.id))
      root.current.releasePointerCapture(pointer.id);
  }, [activity, expansion]);

  const settle = useCallback(
    (index: number, immediate = false) => {
      animation.current?.stop();
      const complete = () => {
        tracking.current = false;
        animation.current = null;
        wheelTarget.current = null;
        activity.set(0);
      };
      if (immediate || latest.current.reducedMotion) {
        position.jump(index);
        complete();
      } else
        animation.current = animate(position, index, {
          ...SPRING_LAYOUT,
          onComplete: complete,
        });
    },
    [activity, position],
  );

  useLayoutEffect(() => {
    const changed = previousConfiguration.current !== configuration;
    previousConfiguration.current = configuration;
    // An accepted live selection must not cancel the gesture or snap its
    // floating position. External changes still own the control immediately.
    if (changed || !tracking.current || selectedValue !== request.current) {
      stop();
      request.current = selectedValue;
      settle(selectedIndex, instant.current || disabled || !!reducedMotion);
    }
    if (changed) {
      suppressClick.current = false;
    }
    instant.current = false;
    if (focusWithin.current && selectedValue !== undefined && !disabled) {
      buttons.current.get(selectedValue)?.focus({ preventScroll: true });
    }
  }, [
    selectedValue,
    selectedIndex,
    configuration,
    disabled,
    reducedMotion,
    settle,
    stop,
  ]);

  const publish = useCallback(
    (index: number, keyboard = false) => {
      const current = latest.current;
      const option = current.options[index];
      if (!option || option.disabled || current.disabled) return;
      if (option.value === request.current) return;
      request.current = option.value;
      if (!current.controlled) setInternalValue(option.value);
      current.onValueChange?.(option.value);
      if (!current.controlled) return;
      cancelAnimationFrame(reconcileFrame.current);
      // Give React a full frame to commit the consumer's update before checking
      // for rejection. A same-frame RAF can run before that commit and cancel
      // an accepted gesture, especially when a detent is crossed inside a RAF.
      reconcileFrame.current = requestAnimationFrame(() => {
        reconcileFrame.current = requestAnimationFrame(() => {
          if (
            request.current !== option.value ||
            latest.current.selectedValue === option.value
          )
            return;
          stop();
          request.current = latest.current.selectedValue;
          settle(latest.current.selectedIndex, keyboard);
          if (
            (keyboard || focusWithin.current) &&
            latest.current.selectedValue !== undefined
          ) {
            buttons.current
              .get(latest.current.selectedValue)
              ?.focus({ preventScroll: true });
          }
        });
      });
    },
    [settle, stop],
  );

  const select = useCallback(
    (index: number, keyboard = false) => {
      const current = latest.current;
      const option = current.options[index];
      if (!option || option.disabled || current.disabled) return;
      stop();
      instant.current = keyboard;
      if (keyboard) {
        expansion.jump(0);
        frameWidth.jump(frameTarget.get());
      }
      publish(index, keyboard);
      settle(index, keyboard);
      if (keyboard)
        buttons.current.get(option.value)?.focus({ preventScroll: true });
    },
    [expansion, frameTarget, frameWidth, publish, settle, stop],
  );

  const nearestEnabled = useCallback((at: number) => {
    let nearest = -1;
    let distance = Infinity;
    latest.current.options.forEach((option, index) => {
      if (!option.disabled && Math.abs(index - at) < distance) {
        nearest = index;
        distance = Math.abs(index - at);
      }
    });
    return nearest;
  }, []);

  useEffect(
    () =>
      position.on("change", (at) => {
        if (!tracking.current || latest.current.disabled) return;
        const next = nearestEnabled(at);
        if (next < 0) return;
        const previous = latest.current.options.findIndex(
          (option) => option.value === request.current,
        );
        // A large frame delta may cross several detents. Notify each enabled
        // choice in order; never wait for the wheel-idle timer or pointer release.
        const step = next > previous ? 1 : -1;
        if (previous < 0 || previous === next) publish(next);
        else
          for (
            let index = previous + step;
            step > 0 ? index <= next : index >= next;
            index += step
          )
            publish(index);
      }),
    [nearestEnabled, position, publish],
  );

  useEffect(() => {
    const element = root.current;
    if (!element) return;
    const wheel = (event: WheelEvent) => {
      const current = latest.current;
      if (
        current.disabled ||
        event.ctrlKey ||
        drag.current?.moved ||
        !current.options.some((option) => !option.disabled)
      )
        return;
      const useX = Math.abs(event.deltaX) > Math.abs(event.deltaY);
      if (!current.horizontal && useX) return;
      const delta =
        (current.horizontal && useX ? event.deltaX : event.deltaY) *
        (event.deltaMode === 1
          ? 16
          : event.deltaMode === 2
            ? current.horizontal
              ? element.clientWidth
              : element.clientHeight
            : 1);
      if (!delta) return;
      const enabled = current.options
        .map((option, index) => ({ option, index }))
        .filter(({ option }) => !option.disabled);
      const first = enabled[0]?.index ?? 0;
      const last = enabled[enabled.length - 1]?.index ?? first;
      const from = wheelTarget.current ?? position.get();
      // At an end, release wheel events back to the page's own scroll.
      if ((from <= first && delta < 0) || (from >= last && delta > 0)) return;
      event.preventDefault();
      if (wheelTimer.current) clearTimeout(wheelTimer.current);
      if (current.reducedMotion) {
        const at = enabled.findIndex(
          ({ option }) => option.value === request.current,
        );
        const next =
          enabled[clamp(at + Math.sign(delta), 0, enabled.length - 1)];
        if (next) select(next.index, true);
      } else {
        if (wheelTarget.current === null) {
          animation.current?.stop();
          animation.current = null;
        }
        instant.current = false;
        tracking.current = true;
        activity.set(1);
        const next = clamp(from + delta / current.spacing, first, last);
        // Wheel deltas already contain trackpad momentum. Follow them directly;
        // useTransform coalesces visual writes to one per frame. A spring here
        // lags behind frequent input and can feel stuck until scrolling stops.
        wheelTarget.current = next;
        position.set(next);
        wheelTimer.current = setTimeout(() => {
          wheelTimer.current = null;
          wheelTarget.current = null;
          settle(nearestEnabled(next));
        }, WHEEL_SETTLE_MS);
      }
    };
    element.addEventListener("wheel", wheel, { passive: false });
    return () => {
      element.removeEventListener("wheel", wheel);
      stop();
    };
  }, [activity, nearestEnabled, position, select, settle, stop]);

  const keyboard = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || disabled) return;
    const enabled = options
      .map((option, index) => ({ option, index }))
      .filter(({ option }) => !option.disabled);
    if (!enabled.length) return;
    const at = Math.max(
      0,
      enabled.findIndex(({ option }) => option.value === request.current),
    );
    let next: number;
    switch (event.key) {
      case "ArrowDown":
      case "ArrowRight":
        next = at + (event.shiftKey ? 5 : 1);
        break;
      case "ArrowUp":
      case "ArrowLeft":
        next = at - (event.shiftKey ? 5 : 1);
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = enabled.length - 1;
        break;
      case "PageDown":
        next = at + 5;
        break;
      case "PageUp":
        next = at - 5;
        break;
      default:
        return;
    }
    event.preventDefault();
    const option = enabled[clamp(next, 0, enabled.length - 1)];
    if (option) select(option.index, true);
  };

  const release = (event: PointerEvent<HTMLDivElement>, cancelled: boolean) => {
    const current = drag.current;
    if (!current || current.id !== event.pointerId) return;
    drag.current = null;
    if (root.current?.hasPointerCapture(event.pointerId))
      root.current.releasePointerCapture(event.pointerId);
    if (!current.moved) return;
    suppressClick.current = true;
    if (cancelled) {
      tracking.current = false;
      activity.set(0);
      settle(latest.current.selectedIndex);
    } else {
      const velocity =
        performance.now() - current.time > 100 ? 0 : current.velocity;
      settle(
        nearestEnabled(
          position.get() + (reducedMotion ? 0 : velocity * COAST_SECONDS),
        ),
      );
    }
  };

  return (
    <div
      {...props}
      ref={root}
      role="radiogroup"
      aria-label={label}
      aria-describedby={[describedBy, instructionsId].filter(Boolean).join(" ")}
      aria-disabled={disabled || undefined}
      aria-orientation={horizontal ? "horizontal" : "vertical"}
      data-slot="arc-picker"
      data-side={side}
      className={cn(
        "relative w-full min-w-0 cursor-grab select-none overflow-hidden active:cursor-grabbing",
        disabled && "cursor-default opacity-50",
        className,
      )}
      style={{
        touchAction: horizontal ? "pan-y pinch-zoom" : "pan-x pinch-zoom",
        height: horizontal ? horizontalHeight : count * rowHeight,
        maskImage: `linear-gradient(to ${horizontal ? "right" : "bottom"}, transparent, black 12%, black 88%, transparent)`,
        ...style,
      }}
      onKeyDown={keyboard}
      onFocusCapture={(event) => {
        focusWithin.current = true;
        onFocusCapture?.(event);
      }}
      onBlurCapture={(event) => {
        if (event.relatedTarget && !root.current?.contains(event.relatedTarget))
          focusWithin.current = false;
        onBlurCapture?.(event);
      }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (
          event.defaultPrevented ||
          disabled ||
          selectedValue === undefined ||
          event.button !== 0 ||
          !event.isPrimary
        )
          return;
        stop();
        suppressClick.current = false;
        const coordinate = horizontal ? event.clientX : event.clientY;
        drag.current = {
          id: event.pointerId,
          coordinate,
          position: position.get(),
          lastCoordinate: coordinate,
          time: performance.now(),
          velocity: 0,
          moved: false,
        };
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        const current = drag.current;
        if (
          event.defaultPrevented ||
          !current ||
          current.id !== event.pointerId
        )
          return;
        const coordinate = horizontal ? event.clientX : event.clientY;
        const delta = coordinate - current.coordinate;
        if (!current.moved && Math.abs(delta) < 6) return;
        current.moved = true;
        tracking.current = true;
        instant.current = false;
        activity.set(reducedMotion ? 0 : 1);
        root.current?.setPointerCapture(event.pointerId);
        const now = performance.now();
        const elapsed = Math.max(8, now - current.time);
        current.velocity =
          current.velocity * 0.35 +
          ((current.lastCoordinate - coordinate) / spacing / elapsed) *
            1000 *
            0.65;
        current.lastCoordinate = coordinate;
        current.time = now;
        const next = clamp(
          current.position - delta / spacing,
          0,
          Math.max(0, options.length - 1),
        );
        position.set(reducedMotion ? Math.round(next) : next);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        release(event, false);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        release(event, true);
      }}
      onLostPointerCapture={(event) => {
        onLostPointerCapture?.(event);
        release(event, true);
      }}
      onClickCapture={(event) => {
        onClickCapture?.(event);
        if (suppressClick.current && event.detail > 0) {
          event.preventDefault();
          event.stopPropagation();
          suppressClick.current = false;
        }
      }}
    >
      <span id={instructionsId} className="sr-only">
        Drag {horizontal ? "horizontally" : "vertically"} or scroll to choose.
        Use arrow keys to move, Home and End to jump.
      </span>
      {name && (
        <input
          type="hidden"
          name={name}
          value={selectedValue ?? ""}
          disabled={disabled}
        />
      )}
      {options.map((option, index) => (
        <ArcOption
          key={option.value}
          option={option}
          index={index}
          position={position}
          verticalAnchor={verticalAnchor}
          radius={curveRadius}
          itemHeight={spacing}
          visibleCount={shownCount}
          side={side}
          selected={option.value === selectedValue}
          disabled={disabled}
          setRef={(element) => {
            if (element) buttons.current.set(option.value, element);
            else buttons.current.delete(option.value);
          }}
          onSelect={() => select(index)}
        />
      ))}
      <ArcSelectionFrame
        width={frameWidth}
        expansion={expansion}
        side={side}
        verticalAnchor={verticalAnchor}
        visible={selectedValue !== undefined}
      />
      {!options.length && (
        <span className="absolute inset-0 flex items-center justify-center text-sm text-muted-foreground">
          No options
        </span>
      )}
    </div>
  );
}

