"use client";

import { type RefObject, useEffect, useLayoutEffect, useRef } from "react";

const FOCUSABLE =
  'button:not(:disabled), a[href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex="-1"])';

/** Elements inside `container` that Tab can reach, in DOM order. */
export function focusablesIn(container: Element | null) {
  return Array.from(
    container?.querySelectorAll<HTMLElement>(FOCUSABLE) ?? [],
  ).filter((element) => element.tabIndex >= 0 && !element.closest("[inert]"));
}

/**
 * Open traps, innermost last. Only the innermost one answers Tab, Escape and
 * stray focus: a sheet opened from inside a drawer portals outside the drawer,
 * and a drawer that still pulled focus home would fight the sheet for it.
 */
const traps: object[] = [];

export interface FocusTrapOptions {
  /** Called on Escape while this is the innermost open trap. */
  onEscape?: () => void;
}

/**
 * Moves focus into `panel` when `open` turns true, keeps Tab cycling inside it,
 * pulls focus back if it lands outside, and returns focus to whatever held it
 * before opening once `open` turns false.
 *
 * For overlays rendered in place, where `useModalScope` cannot inert the rest
 * of the page. Pass `open` rather than presence: an exiting panel is already
 * inert through `PresenceGate`, so the trap releases with the same commit.
 * Give the panel `tabIndex={-1}` so it can take focus when it holds nothing
 * focusable.
 */
export function useFocusTrap(
  open: boolean,
  panel: RefObject<HTMLElement | null>,
  { onEscape }: FocusTrapOptions = {},
) {
  const escapeRef = useRef(onEscape);
  useLayoutEffect(() => {
    escapeRef.current = onEscape;
  });

  useEffect(() => {
    if (!open || !panel.current) return;
    const self = {};
    traps.push(self);
    const innermost = () => traps[traps.length - 1] === self;
    const returnFocus =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    const focusables = () => focusablesIn(panel.current);    const focusFirst = () =>
      (focusables()[0] ?? panel.current)?.focus({ preventScroll: true });
    if (!panel.current.contains(document.activeElement)) focusFirst();

    const onFocus = (event: FocusEvent) => {
      if (!innermost() || !panel.current || panel.current.closest("[inert]"))
        return;
      if (event.target instanceof Node && !panel.current.contains(event.target))
        focusFirst();
    };
    const onKey = (event: KeyboardEvent) => {
      if (!innermost() || event.defaultPrevented) return;
      if (event.key === "Escape" && escapeRef.current) {
        event.preventDefault();
        escapeRef.current();
        return;
      }
      if (event.key !== "Tab") return;
      const elements = focusables();
      const first = elements[0];
      const last = elements[elements.length - 1];
      const active = document.activeElement;
      if (!first || !last) {
        event.preventDefault();
        panel.current?.focus({ preventScroll: true });
      } else if (event.shiftKey && (active === first || active === panel.current)) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("focusin", onFocus);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("focusin", onFocus);
      document.removeEventListener("keydown", onKey);
      traps.splice(traps.indexOf(self), 1);
      if (returnFocus?.isConnected && !returnFocus.closest("[inert]"))
        returnFocus.focus({ preventScroll: true });
    };
  }, [open, panel]);
}

"use client";

import { useIsPresent } from "motion/react";
import type { ReactNode } from "react";

export interface PresenceGateRenderProps {
  /**
   * False from the render that starts the exit animation onward. An overlay
   * kept in the tree by `AnimatePresence` is still the topmost thing on the
   * page, so anything it decides from `open` alone stays true for the whole
   * exit — this is the boolean that already knows the overlay is leaving.
   */
  isPresent: boolean;
  /**
   * Spread onto every layer that takes pointer events while the overlay is
   * open. Interaction releases in the same commit that starts the exit while
   * the visual exit keeps playing: pointer events stop landing, and `inert`
   * drops the subtree from focus order, from tab order and from the
   * accessibility tree — an exiting dialog is not a dialog you can still type
   * into. A layer that never takes pointer events (a wrapper that only centres
   * the panel) takes `inert={!isPresent}` alone, so its own
   * `pointer-events-none` is not overwritten.
   */
  gate: {
    inert: boolean;
    style: { pointerEvents: "auto" | "none" };
  };
}

export interface PresenceGateProps {
  children: (props: PresenceGateRenderProps) => ReactNode;
}

/**
 * Reads the presence of the subtree it renders and hands it down.
 *
 * `useIsPresent` only answers inside the `AnimatePresence` subtree, and the
 * components that own an overlay render the `AnimatePresence` themselves, so
 * the boolean has to be read one component further down: this is that
 * component, and the render prop is how it reaches the layers.
 */
export function PresenceGate({ children }: PresenceGateProps) {
  const isPresent = useIsPresent();

  return children({
    isPresent,
    gate: {
      inert: !isPresent,
      style: { pointerEvents: isPresent ? "auto" : "none" },
    },
  });
}

