interface TreemapBase {
  /** Unique across the whole tree. Retain IDs when updating values. */
  id: string;
  label: string;
  color?: string;
  textColor?: string;
  description?: string;
}

export interface TreemapLeaf extends TreemapBase {
  /** Finite, nonnegative weight. Zero values stay in the accessible table. */
  value: number;
}

export interface TreemapGroup extends TreemapBase {
  /** Group weights are derived from their leaves; groups never add their own value. */
  children: readonly TreemapNode[];
}

export type TreemapNode = TreemapLeaf | TreemapGroup;

export interface TreemapItem extends TreemapLeaf {
  color: string;
  textColor: string;
  path: readonly string[];
  share: number;
}

interface ResolvedNode {
  id: string;
  label: string;
  value: number;
  color: string;
  children: ResolvedNode[];
  item: TreemapItem | null;
}

export interface TreemapTile extends TreemapItem {
  x: number;
  y: number;
  width: number;
  height: number;
}

export const TREEMAP_COLORS = [
  "#1d4ed8",
  "#7c3aed",
  "#0f766e",
  "#b45309",
  "#be123c",
  "#475569",
] as const;

export function buildTreemap(
  data: readonly TreemapNode[],
  colors: readonly string[],
  textColor: string,
) {
  if (!colors.length) throw new Error("Treemap: colors must contain at least one color.");
  const ids = new Set<string>();
  const items: TreemapItem[] = [];
  const resolve = (
    node: TreemapNode,
    path: readonly string[],
    inheritedColor: string,
    inheritedText: string,
  ): ResolvedNode => {
    if (ids.has(node.id)) throw new Error(`Treemap: duplicate node ID "${node.id}".`);
    ids.add(node.id);
    const color = node.color ?? inheritedColor;
    const foreground = node.textColor ?? inheritedText;
    const nextPath = [...path, node.label];
    if ("children" in node) {
      const children = node.children.map((child) => resolve(child, nextPath, color, foreground));
      const value = children.reduce((sum, child) => sum + child.value, 0);
      if (!Number.isFinite(value)) throw new Error("Treemap: group totals must remain finite.");
      return { id: node.id, label: node.label, value, color, children, item: null };
    }
    if (!Number.isFinite(node.value) || node.value < 0)
      throw new Error("Treemap: leaf values must be finite and nonnegative.");
    const item: TreemapItem = { ...node, color, textColor: foreground, path: nextPath, share: 0 };
    items.push(item);
    return { id: node.id, label: node.label, value: node.value, color, children: [], item };
  };
  const nodes = data.map((node, index) =>
    resolve(node, [], colors[index % colors.length], textColor),
  );
  const total = nodes.reduce((sum, node) => sum + node.value, 0);
  if (!Number.isFinite(total)) throw new Error("Treemap: the total must remain finite.");
  for (const item of items) item.share = total ? item.value / total : 0;
  return { nodes, items, total };
}

/** Order-preserving balanced binary tiling, recursively applied to groups.
 * See https://d3js.org/d3-hierarchy/treemap#treemapBinary for the tiling method.
 * The calculation is local and never generates values or mutates consumer data. */
export function layoutTreemap(nodes: readonly ResolvedNode[], width: number, height: number) {
  const tiles: TreemapTile[] = [];
  const partition = (
    siblings: readonly ResolvedNode[],
    x: number,
    y: number,
    w: number,
    h: number,
  ) => {
    const positive = siblings.filter((node) => node.value > 0);
    if (!positive.length) return;
    if (positive.length === 1) {
      const node = positive[0];
      if (node.item) tiles.push({ ...node.item, x, y, width: w, height: h });
      else partition(node.children, x, y, w, h);
      return;
    }
    const total = positive.reduce((sum, node) => sum + node.value, 0);
    let cut = 1;
    let subtotal = positive[0].value;
    for (let i = 1; i < positive.length - 1; i++) {
      const next = subtotal + positive[i].value;
      if (Math.abs(next - total / 2) > Math.abs(subtotal - total / 2)) break;
      cut = i + 1;
      subtotal = next;
    }
    const fraction = subtotal / total;
    if (w >= h) {
      const split = w * fraction;
      partition(positive.slice(0, cut), x, y, split, h);
      partition(positive.slice(cut), x + split, y, w - split, h);
    } else {
      const split = h * fraction;
      partition(positive.slice(0, cut), x, y, w, split);
      partition(positive.slice(cut), x, y + split, w, h - split);
    }
  };
  partition(nodes, 0, 0, width, height);
  return tiles.filter((tile) => tile.width > 0 && tile.height > 0);
}

"use client";

import { AnimatePresence, LayoutGroup } from "motion/react";
import { useId, useLayoutEffect, useRef, type KeyboardEvent, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useTreemap } from "./context";
import type { TreemapTile } from "./model";
import { TreemapCell } from "./tile";

export interface TreemapPlotProps {
  /** Sets the plot height; default 20rem. The layout follows its measured dimensions. */
  className?: string;
  tileClassName?: string;
  /** Return presentation content only; each tile already owns its button and accessible name. */
  renderTile?: (tile: TreemapTile) => ReactNode;
}

export function TreemapPlot({ className, tileClassName, renderTile }: TreemapPlotProps) {
  const { tiles, items, plotRef, setSize, cursor, buttons, setActive, setTooltipOpen } =
    useTreemap();
  const layoutId = useId();
  const focusedId = useRef<string | null>(null);
  useLayoutEffect(() => {
    const plot = plotRef.current;
    if (!plot) return;
    const measure = () => {
      const { width, height } = plot.getBoundingClientRect();
      if (width > 0 && height > 0)
        setSize((size) =>
          size.width === width && size.height === height ? size : { width, height },
        );
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(plot);
    return () => observer.disconnect();
  }, [plotRef, setSize]);
  useLayoutEffect(() => {
    const id = focusedId.current;
    if (!id || tiles.some((tile) => tile.id === id)) return;
    focusedId.current = null;
    const lost = buttons.current.get(id);
    if (document.activeElement === lost || document.activeElement === document.body) {
      const replacement = tiles[cursor.activeIndex];
      if (replacement) buttons.current.get(replacement.id)?.focus();
      else plotRef.current?.focus();
    }
  }, [tiles, cursor.activeIndex, buttons, plotRef]);
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!(event.target instanceof HTMLButtonElement)) return;
    const id = event.target.dataset.treemapTile;
    const current = tiles.find((tile) => tile.id === id);
    if (!current) return;
    if (event.key === "Escape") {
      setTooltipOpen(false);
      return;
    }
    if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(event.key))
      return;
    event.preventDefault();
    let next = current;
    if (event.key === "Home") next = tiles[0];
    else if (event.key === "End") next = tiles[tiles.length - 1];
    else {
      const horizontal = event.key === "ArrowLeft" || event.key === "ArrowRight";
      const direction = event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 1;
      const cx = current.x + current.width / 2;
      const cy = current.y + current.height / 2;
      let best = Number.POSITIVE_INFINITY;
      for (const tile of tiles) {
        const dx = tile.x + tile.width / 2 - cx;
        const dy = tile.y + tile.height / 2 - cy;
        const forward = (horizontal ? dx : dy) * direction;
        const cross = Math.abs(horizontal ? dy : dx);
        const score = forward + cross * 2;
        if (forward > 0.01 && score < best) {
          next = tile;
          best = score;
        }
      }
    }
    setTooltipOpen(true);
    if (next.id === current.id) setActive(current.id);
    else buttons.current.get(next.id)?.focus();
  };
  return (
    <LayoutGroup id={layoutId}>
      {/* biome-ignore lint/a11y/useSemanticElements: This group is a chart, not a collection of form fields. */}
      <div
        ref={plotRef}
        role="group"
        aria-label="Treemap tiles"
        tabIndex={-1}
        data-slot="treemap-plot"
        className={cn(
          "relative h-80 w-full min-w-0 rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring",
          className,
        )}
        onKeyDown={onKeyDown}
        onFocus={(event) => {
          if (event.target instanceof HTMLButtonElement)
            focusedId.current = event.target.dataset.treemapTile ?? null;
        }}
        onBlur={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget)) {
            focusedId.current = null;
            setTooltipOpen(false);
          }
        }}
        onPointerLeave={() => setTooltipOpen(false)}
      >
        <AnimatePresence initial={false}>
          {tiles.map((tile) => (
            <TreemapCell
              key={tile.id}
              tile={tile}
              className={tileClassName}
              renderTile={renderTile}
            />
          ))}
        </AnimatePresence>
        {!tiles.length ? (
          <p className="flex h-full items-center justify-center text-sm text-muted-foreground">
            {items.length ? "No positive values" : "No treemap data"}
          </p>
        ) : null}
      </div>
    </LayoutGroup>
  );
}

"use client";

import { motion, useIsPresent } from "motion/react";
import { useCallback, type ReactNode } from "react";
import { EASE_OUT, SPRING_LAYOUT } from "@/lib/ease";
import { cn } from "@/lib/utils";
import { useTreemap } from "./context";
import type { TreemapTile } from "./model";

export function TreemapCell({
  tile,
  className,
  renderTile,
}: {
  tile: TreemapTile;
  className?: string;
  renderTile?: (tile: TreemapTile) => ReactNode;
}) {
  const {
    size,
    active,
    setActive,
    cursor,
    tiles,
    formatValue,
    tooltipId,
    tooltipOpen,
    setTooltipOpen,
    reduce,
    canHover,
    registerButton,
  } = useTreemap();
  const present = useIsPresent();
  const ref = useCallback(
    (node: HTMLButtonElement | null) => registerButton(tile.id, node),
    [tile.id, registerButton],
  );
  const selected = tooltipOpen && active?.id === tile.id;
  const width = tile.width / size.width;
  const height = tile.height / size.height;
  // Small tiles remain inspectable; their labels stay in the accessible name
  // and exact-data table rather than spilling into neighbouring rectangles.
  const showLabel = tile.width >= 52 && tile.height >= 32;
  const showValue = tile.width >= 70 && tile.height >= 56;
  return (
    <motion.button
      ref={ref}
      type="button"
      data-treemap-tile={tile.id}
      layout={!reduce}
      inert={!present}
      aria-hidden={!present || undefined}
      tabIndex={present && tiles[cursor.activeIndex]?.id === tile.id ? 0 : -1}
      aria-label={[
        tile.path.join(" / "),
        formatValue(tile.value),
        `${(tile.share * 100).toFixed(1)}% of total`,
        tile.description,
      ]
        .filter(Boolean)
        .join(". ")}
      aria-describedby={present && selected ? tooltipId : undefined}
      className={cn(
        "absolute overflow-hidden border-2 border-background text-left outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-white",
        className,
      )}
      style={{
        left: `${(tile.x / size.width) * 100}%`,
        top: `${(tile.y / size.height) * 100}%`,
        width: `${width * 100}%`,
        height: `${height * 100}%`,
        backgroundColor: tile.color,
        color: tile.textColor,
        borderRadius: 8,
        pointerEvents: present ? "auto" : "none",
      }}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{
        layout: reduce ? { duration: 0 } : SPRING_LAYOUT,
        opacity: { type: "tween", duration: present ? 0.18 : 0.1, ease: EASE_OUT },
      }}
      onPointerEnter={(event) => {
        if (present && canHover && event.pointerType !== "touch") {
          setActive(tile.id);
          setTooltipOpen(true);
        }
      }}
      onPointerMove={(event) => {
        if (present && (event.pointerType === "touch" ? event.buttons === 1 : canHover)) {
          setActive(tile.id);
          setTooltipOpen(true);
        }
      }}
      onPointerDown={() => {
        if (present) {
          setActive(tile.id);
          setTooltipOpen(true);
        }
      }}
      onClick={() => {
        if (present) {
          setActive(tile.id);
          setTooltipOpen(true);
        }
      }}
      onFocus={() => {
        if (present) {
          cursor.moveTo(tile.id);
          setActive(tile.id);
          setTooltipOpen(true);
        }
      }}
    >
      <motion.span
        aria-hidden="true"
        layout={reduce ? false : "position"}
        transition={reduce ? { duration: 0 } : SPRING_LAYOUT}
        className="absolute inset-x-2 top-2 min-w-0 sm:inset-x-3 sm:top-3"
      >
        {renderTile ? (
          renderTile(tile)
        ) : showLabel ? (
          <>
            <span className="block truncate text-xs font-semibold sm:text-sm">{tile.label}</span>
            {showValue ? (
              <span className="mt-1 block truncate font-mono text-[10px] tabular-nums opacity-80 sm:text-xs">
                {formatValue(tile.value)}
              </span>
            ) : null}
          </>
        ) : null}
      </motion.span>
      <motion.span
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 bg-white/10"
        initial={false}
        animate={{ opacity: selected ? 1 : 0 }}
        transition={{ type: "tween", duration: 0.1, ease: EASE_OUT }}
      />
    </motion.button>
  );
}

