"use client";

import { useReducedMotion } from "motion/react";
import {
  createContext,
  useCallback,
  useContext,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
} from "react";
import { useHoverCapable } from "@/lib/hooks/use-hover-capable";
import { buildVolumeProfile, type VolumeProfileBin } from "./model";

const formatNumber = (value: number) => value.toLocaleString("en-US", { maximumFractionDigits: 2 });

export interface VolumeProfileProps extends ComponentProps<"section"> {
  /** Already-aggregated executed volume. Sorted by price; unequal bins and gaps are supported. */
  data: readonly VolumeProfileBin[];
  label?: string;
  unit?: string;
  formatPrice?: (price: number) => string;
  formatVolume?: (volume: number) => string;
  /** Target fraction, default 0.7. Whole bins may cover less; the POC is always included.
   * Set false to hide the value area. Equal-volume POCs favor the lower price. */
  valueArea?: number | false;
  color?: string;
  pocColor?: string;
  activeId?: string | null;
  defaultActiveId?: string | null;
  onActiveChange?: (id: string | null) => void;
}

export function useVolumeProfileModel({
  data,
  label = "Volume profile",
  unit = "units",
  formatPrice = formatNumber,
  formatVolume = formatNumber,
  valueArea = 0.7,
  color = "#6366f1",
  pocColor = "#f59e0b",
  activeId,
  defaultActiveId = null,
  onActiveChange,
}: VolumeProfileProps) {
  const model = useMemo(() => buildVolumeProfile(data, valueArea), [data, valueArea]);
  const [internalId, setInternalId] = useState(defaultActiveId);
  if (internalId !== null && !model.rows.some((row) => row.id === internalId)) setInternalId(null);
  const requestedId = activeId === undefined ? internalId : activeId;
  const activeIndex = model.rows.findIndex((row) => row.id === requestedId);
  const active = model.rows[activeIndex] ?? null;
  const [tooltipOpen, setTooltipOpen] = useState(false);
  const plotRef = useRef<HTMLDivElement>(null);
  const tooltipId = useId();
  const latest = useRef({ activeId, requestedId, onActiveChange });
  useLayoutEffect(() => {
    latest.current = { activeId, requestedId, onActiveChange };
  });
  const setActive = useCallback((id: string | null) => {
    const current = latest.current;
    if (current.activeId === undefined) setInternalId(id);
    if (current.requestedId !== id) current.onActiveChange?.(id);
  }, []);
  const describe = (row: (typeof model.rows)[number]) =>
    [
      `${formatPrice(row.priceLow)} to ${formatPrice(row.priceHigh)}`,
      `${formatVolume(row.volume)} ${unit}`,
      `${(row.share * 100).toFixed(1)}% of total volume`,
      row.isPoc ? "Point of control" : row.inValueArea ? "Inside value area" : null,
    ]
      .filter(Boolean)
      .join(". ");
  return {
    ...model,
    label,
    unit,
    formatPrice,
    formatVolume,
    color,
    pocColor,
    describe,
    active,
    activeIndex,
    setActive,
    plotRef,
    tooltipId,
    tooltipOpen,
    setTooltipOpen,
    reduce: useReducedMotion(),
    canHover: useHoverCapable(),
  };
}

export const VolumeProfileContext = createContext<ReturnType<typeof useVolumeProfileModel> | null>(
  null,
);

export function useVolumeProfile() {
  const context = useContext(VolumeProfileContext);
  if (!context) throw new Error("Volume profile parts must be rendered inside VolumeProfile.");
  return context;
}

export interface VolumeProfileBin {
  /** Stable identity for this price range across data updates. */
  id: string;
  priceLow: number;
  priceHigh: number;
  /** Executed volume in this range, in the consumer's chosen unit. */
  volume: number;
}

export function buildVolumeProfile(data: readonly VolumeProfileBin[], target: number | false) {
  if (target !== false && (!Number.isFinite(target) || target <= 0 || target > 1))
    throw new Error("VolumeProfile: valueArea must be a fraction above 0 and at most 1, or false.");
  const bins = [...data].sort((a, b) => a.priceLow - b.priceLow);
  const ids = new Set<string>();
  let totalVolume = 0;
  let maxVolume = 0;
  let pocIndex = -1;
  for (const [index, bin] of bins.entries()) {
    if (ids.has(bin.id)) throw new Error(`VolumeProfile: duplicate bin ID "${bin.id}".`);
    ids.add(bin.id);
    if (
      !Number.isFinite(bin.priceLow) ||
      !Number.isFinite(bin.priceHigh) ||
      bin.priceHigh <= bin.priceLow ||
      !Number.isFinite(bin.volume) ||
      bin.volume < 0
    )
      throw new Error(
        "VolumeProfile: bins need finite increasing price bounds and nonnegative volume.",
      );
    if (index > 0 && bin.priceLow < bins[index - 1].priceHigh)
      throw new Error("VolumeProfile: price ranges must not overlap.");
    totalVolume += bin.volume;
    // Equal maxima keep the lower-price bin as a deterministic POC.
    if (bin.volume > maxVolume) {
      maxVolume = bin.volume;
      pocIndex = index;
    }
  }
  const priceLow = bins[0]?.priceLow ?? 0;
  const priceHigh = bins.at(-1)?.priceHigh ?? 1;
  const span = priceHigh - priceLow;
  if (!Number.isFinite(totalVolume) || !Number.isFinite(span))
    throw new Error("VolumeProfile: the total volume and price span must remain finite.");
  let lowIndex = pocIndex;
  let highIndex = pocIndex;
  let areaVolume = pocIndex >= 0 ? bins[pocIndex].volume : 0;
  if (target === 1 && pocIndex >= 0) {
    // A 100% target includes every bin, including empty edge bins, without
    // depending on floating-point summation order during adjacent expansion.
    lowIndex = 0;
    highIndex = bins.length - 1;
    areaVolume = totalVolume;
  } else if (target !== false && pocIndex >= 0) {
    const targetVolume = totalVolume * target;
    // Grow a contiguous area from the POC using the larger adjacent volume.
    // Ties favor the nearer row, then the higher price. Stop before adding a
    // row that would exceed the target; the POC itself is always included.
    while (areaVolume < targetVolume) {
      const below = bins[lowIndex - 1];
      const above = bins[highIndex + 1];
      if (!below && !above) break;
      const takeAbove =
        !below ||
        (!!above &&
          (above.volume > below.volume ||
            (above.volume === below.volume &&
              highIndex + 1 - pocIndex <= pocIndex - (lowIndex - 1))));
      const next = takeAbove ? above : below;
      if (!next || areaVolume + next.volume > targetVolume) break;
      areaVolume += next.volume;
      if (takeAbove) highIndex++;
      else lowIndex--;
    }
  }
  const valueArea =
    target !== false && pocIndex >= 0
      ? {
          priceLow: bins[lowIndex].priceLow,
          priceHigh: bins[highIndex].priceHigh,
          volume: areaVolume,
          share: areaVolume / totalVolume,
          target,
        }
      : null;
  const rows = bins.map((bin, index) => ({
    ...bin,
    price: bin.priceLow + (bin.priceHigh - bin.priceLow) / 2,
    top: (priceHigh - bin.priceHigh) / span,
    height: (bin.priceHigh - bin.priceLow) / span,
    center: (priceHigh - (bin.priceLow + (bin.priceHigh - bin.priceLow) / 2)) / span,
    proportion: maxVolume ? bin.volume / maxVolume : 0,
    share: totalVolume ? bin.volume / totalVolume : 0,
    isPoc: index === pocIndex,
    inValueArea: valueArea !== null && index >= lowIndex && index <= highIndex,
  }));
  return {
    rows,
    poc: rows[pocIndex] ?? null,
    valueArea,
    totalVolume,
    maxVolume,
    priceLow,
    priceHigh,
  };
}

export type VolumeProfileRow = ReturnType<typeof buildVolumeProfile>["rows"][number];

"use client";

import { motion } from "motion/react";
import { useRef, type PointerEvent, type ReactNode } from "react";
import { EASE_OUT, SPRING_LAYOUT } from "@/lib/ease";
import { cn } from "@/lib/utils";
import { useVolumeProfile } from "./context";

export interface VolumeProfilePlotProps {
  className?: string;
  barClassName?: string;
  /** Plot height is set by className; default 20rem. */
  showAxes?: boolean;
  children?: ReactNode;
}

export function VolumeProfilePlot({
  className,
  barClassName,
  showAxes = true,
  children,
}: VolumeProfilePlotProps) {
  const {
    rows,
    label,
    maxVolume,
    priceLow,
    priceHigh,
    valueArea,
    formatPrice,
    formatVolume,
    color,
    pocColor,
    activeIndex,
    setActive,
    plotRef,
    tooltipId,
    tooltipOpen,
    setTooltipOpen,
    describe,
    reduce,
    canHover,
  } = useVolumeProfile();
  const pointerDriven = useRef(false);
  const focused = useRef(false);
  const lastPointerId = useRef<string | null>(null);
  const index = Math.max(activeIndex, 0);
  const row = rows[index];
  const inspect = (event: PointerEvent<HTMLInputElement>) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    if (!bounds.height) return;
    const fraction = Math.min(1, Math.max(0, (event.clientY - bounds.top) / bounds.height));
    // Hit-test real price geometry, including unequal bins and empty price gaps.
    const match =
      rows.find((item) => fraction >= item.top && fraction <= item.top + item.height) ??
      rows.reduce((nearest, item) =>
        Math.abs(item.center - fraction) < Math.abs(nearest.center - fraction) ? item : nearest,
      );
    setActive(match.id);
    if (lastPointerId.current !== match.id) setTooltipOpen(true);
    lastPointerId.current = match.id;
  };
  if (!rows.length)
    return (
      <p className={cn("py-12 text-center text-sm text-muted-foreground", className)}>
        No volume data
      </p>
    );
  return (
    <div data-slot="volume-profile-plot" className={cn("min-w-0", showAxes && "pb-6")}>
      <div className={cn("flex h-80 min-w-0 gap-3", className)}>
        {showAxes ? (
          <div
            aria-hidden="true"
            className="relative shrink-0 text-right font-mono text-[10px] tabular-nums text-muted-foreground sm:text-xs"
          >
            {[1, 0.75, 0.5, 0.25, 0].map((position) => (
              <span key={position}>
                <span className="invisible block">
                  {formatPrice(priceLow + (priceHigh - priceLow) * position)}
                </span>
                <span
                  className="absolute right-0 -translate-y-1/2"
                  style={{ top: `${(1 - position) * 100}%` }}
                >
                  {formatPrice(priceLow + (priceHigh - priceLow) * position)}
                </span>
              </span>
            ))}
          </div>
        ) : null}
        <div
          ref={plotRef}
          className="relative min-w-0 flex-1 rounded-sm has-focus-visible:outline-2 has-focus-visible:outline-offset-4 has-focus-visible:outline-ring"
        >
          <div aria-hidden="true" className="pointer-events-none absolute inset-0">
            {[0, 0.25, 0.5, 0.75, 1].map((position) => (
              <span
                key={position}
                className="absolute inset-y-0 border-l border-border/60"
                style={{ left: `${position * 100}%` }}
              />
            ))}
            {rows.map((item, i) => (
              <div
                key={item.id}
                data-volume-bin={item.id}
                data-poc={item.isPoc || undefined}
                data-value-area={item.inValueArea || undefined}
                className="absolute inset-x-0 overflow-hidden py-px"
                style={{ top: `${item.top * 100}%`, height: `${item.height * 100}%` }}
              >
                <motion.div
                  className={cn("h-full w-full rounded-r-sm", barClassName)}
                  style={{
                    backgroundColor: item.isPoc ? pocColor : color,
                    transformOrigin: "left",
                  }}
                  initial={{ opacity: 0, transform: `scaleX(${item.proportion})` }}
                  animate={{
                    opacity: item.isPoc || item.inValueArea || !valueArea ? 0.9 : 0.3,
                    transform: `scaleX(${item.proportion})`,
                  }}
                  transition={{
                    transform: reduce ? { duration: 0 } : SPRING_LAYOUT,
                    opacity: { duration: 0.18, ease: EASE_OUT },
                  }}
                />
                <motion.div
                  className="absolute inset-0 bg-foreground/5"
                  initial={false}
                  animate={{ opacity: tooltipOpen && activeIndex === i ? 1 : 0 }}
                  transition={{ duration: 0.1, ease: EASE_OUT }}
                />
                {item.isPoc ? (
                  <span
                    className="absolute inset-x-0 top-1/2 border-t border-dashed"
                    style={{ borderColor: pocColor }}
                  >
                    <span className="absolute right-0 -translate-y-1/2 rounded bg-background px-1.5 py-0.5 font-mono text-[10px] font-medium text-foreground">
                      POC
                    </span>
                  </span>
                ) : null}
              </div>
            ))}
          </div>
          <input
            type="range"
            min={0}
            max={rows.length - 1}
            step={1}
            value={index}
            aria-label={`${label}: inspect price level`}
            aria-orientation="vertical"
            aria-valuetext={describe(row)}
            aria-describedby={tooltipOpen && activeIndex >= 0 ? tooltipId : undefined}
            className="absolute inset-0 m-0 h-full w-full cursor-crosshair opacity-0"
            style={{ writingMode: "vertical-lr", direction: "rtl", touchAction: "pan-x" }}
            onFocus={() => {
              focused.current = true;
              if (!pointerDriven.current) {
                setActive(row.id);
                setTooltipOpen(true);
              }
            }}
            onBlur={() => {
              focused.current = false;
              pointerDriven.current = false;
              setTooltipOpen(false);
            }}
            onPointerEnter={(event) => {
              if (canHover && event.pointerType !== "touch") inspect(event);
            }}
            onPointerMove={(event) => {
              if (
                event.pointerType === "touch"
                  ? event.buttons === 1
                  : canHover || event.buttons === 1
              )
                inspect(event);
            }}
            onPointerLeave={() => {
              lastPointerId.current = null;
              if (!focused.current || pointerDriven.current) setTooltipOpen(false);
            }}
            onPointerDown={(event) => {
              pointerDriven.current = true;
              lastPointerId.current = null;
              inspect(event);
            }}
            onPointerCancel={() => {
              pointerDriven.current = false;
              setTooltipOpen(false);
            }}
            onClick={() => {
              pointerDriven.current = false;
            }}
            onKeyDown={(event) => {
              pointerDriven.current = false;
              if (event.key === "Escape") setTooltipOpen(false);
              else if (
                ["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Home", "End"].includes(
                  event.key,
                )
              ) {
                if (activeIndex < 0) setActive(row.id);
                setTooltipOpen(true);
              }
            }}
            onChange={(event) => {
              if (pointerDriven.current) return;
              const next = rows[Number(event.target.value)];
              if (next) {
                setActive(next.id);
                setTooltipOpen(true);
              }
            }}
          />
          {showAxes ? (
            <div
              aria-hidden="true"
              className="absolute inset-x-0 top-full mt-2 flex justify-between font-mono text-[10px] tabular-nums text-muted-foreground sm:text-xs"
            >
              <span>0</span>
              <span>{formatVolume(maxVolume / 2)}</span>
              <span>{formatVolume(maxVolume)}</span>
            </div>
          ) : null}
          {children}
        </div>
      </div>
    </div>
  );
}

