            ))}
          </TabsList>
        </div>
        <div id={panelId} role="tabpanel" aria-labelledby={`${id}-${session}`}>
          <VolumeProfile
            data={data[session]}
            label="BTC volume profile"
            unit="BTC"
            formatPrice={formatPrice}
